/* Hallmark · macrostructure: Tactical Console · tone: atmospheric technical · anchor hue: violet */
(function(root){
  'use strict';
  var W=12,H=8,KEY='xxsxShellHeistV1';
  var TYPES={charger:{name:'冲锋壳',mark:'↯',color:'#ffc867',desc:'一次能力可撞开远处闸门。移动快，但转向笨重。'},turret:{name:'炮台壳',mark:'⊙',color:'#ff7e8e',desc:'可远程关闭摄像头。原地不能移动。'},scout:{name:'侦察壳',mark:'⌁',color:'#79e7ee',desc:'扫描后显示隐藏捷径，移动范围最大。'},shield:{name:'护盾壳',mark:'◇',color:'#bb9bff',desc:'展开护盾 5 回合，穿过激光区。'}};
  var DIRS=[[0,-1],[1,0],[0,1],[-1,0]];
  function clone(v){return JSON.parse(JSON.stringify(v));}
  function key(x,y){return x+','+y;}
  function create(){
    var walls={};for(var x=0;x<W;x++){walls[key(x,0)]=1;walls[key(x,H-1)]=1;}for(var y=0;y<H;y++){walls[key(0,y)]=1;walls[key(W-1,y)]=1;}
    [1,2,4,5].forEach(function(y){walls[key(4,y)]=1;});[2,3,4,5,6].forEach(function(y){walls[key(8,y)]=1;});walls[key(4,3)]=1;walls[key(8,6)]=1;
    return {turn:0,alarm:0,phase:'play',message:'先靠近冲锋壳，再按“寄壳”。',player:{x:1,y:6},controlled:'player',shells:[{id:'charger',x:3,y:6,dir:3,active:true,echo:false},{id:'turret',x:6,y:1,dir:1,active:false,echo:false},{id:'scout',x:6,y:6,dir:0,active:false,echo:false},{id:'shield',x:9,y:1,dir:2,active:false,echo:false}],walls:walls,gateOpen:false,shortcut:false,cameraOff:false,shieldTurns:0,terminals:{a:false,b:false},exit:{x:10,y:6},history:[]};
  }
  function actor(s){if(s.controlled==='player')return s.player;return s.shells.find(function(e){return e.id===s.controlled;})||s.player;}
  function occupied(s,x,y,ignore){return s.shells.some(function(e){return e.id!==ignore&&e.x===x&&e.y===y;})||(s.controlled!=='player'&&s.player.x===x&&s.player.y===y);}
  function blocked(s,x,y){if(x<0||y<0||x>=W||y>=H)return true;if(s.walls[key(x,y)]&&!((x===4&&y===3&&s.gateOpen)||(x===8&&y===6&&s.shortcut)))return true;return false;}
  function currentType(s){return s.controlled==='player'?null:TYPES[s.controlled];}
  function canMove(s,x,y){var t=currentType(s);if(blocked(s,x,y)||occupied(s,x,y,s.controlled==='player'?null:s.controlled))return false;if(x===8&&y>=1&&y<=6&&s.controlled!=='player'&&s.controlled!=='shield'&&s.shieldTurns<=0)return false;return true;}
  function stepEchoes(s){s.shells.forEach(function(e){if(e.id===s.controlled||!e.echo)return;e._wait=(e._wait||0)+1;if(e._wait%2)return;var d=DIRS[e.dir%4],nx=e.x+d[0],ny=e.y+d[1];if(canMove(s,nx,ny)){e.x=nx;e.y=ny;}else e.dir=(e.dir+1)%4;});}
  function checkAlarm(s){if(s.alarm>=3){s.phase='lost';s.message='警戒达到 3：巡逻网锁死了设施。';return false;}if(s.terminals.a&&s.terminals.b&&actor(s).x===s.exit.x&&actor(s).y===s.exit.y){s.phase='won';s.message='货物已取出，路线和壳体切换成功。';return false;}return true;}
  function finishTurn(s){s.turn++;if(s.shieldTurns>0)s.shieldTurns--;stepEchoes(s);s.history.push({turn:s.turn,controlled:s.controlled,x:actor(s).x,y:actor(s).y});return checkAlarm(s);}
  function move(s,dx,dy){if(s.phase!=='play')return false;var a=actor(s),nx=a.x+dx,ny=a.y+dy;if(!canMove(s,nx,ny)){s.message='这条路线被墙、壳体或激光挡住了。';return false;}a.x=nx;a.y=ny;s.message='移动到 '+nx+','+ny+'。';finishTurn(s);return true;}
  function possess(s){if(s.phase!=='play')return false;var a=actor(s),candidate=s.shells.filter(function(e){return e.id!==s.controlled&&Math.abs(e.x-a.x)+Math.abs(e.y-a.y)<=1;}).sort(function(x,y){return x.id.localeCompare(y.id);})[0];if(!candidate){s.message='附近没有可寄壳目标。';return false;}if(s.controlled!=='player'){var old=s.shells.find(function(e){return e.id===s.controlled;});if(old){old.echo=true;old.active=false;old.dir=(old.dir+1)%4;}}s.controlled=candidate.id;candidate.echo=false;candidate.active=true;s.message='已寄壳：'+TYPES[candidate.id].name+'。留下的壳会继续按最后方向行动。';finishTurn(s);return true;}
  function leave(s){if(s.phase!=='play'||s.controlled==='player')return false;var old=s.shells.find(function(e){return e.id===s.controlled;});if(!old)return false;old.echo=true;old.active=false;old.dir=(old.dir+1)%4;s.player.x=old.x;s.player.y=old.y;s.controlled='player';s.message='离壳完成。当前壳会继续行动，注意它可能改变路线。';finishTurn(s);return true;}
  function ability(s){if(s.phase!=='play'||s.controlled==='player')return false;var a=actor(s),id=s.controlled;
    if(id==='charger'){if(Math.abs(a.x-4)+Math.abs(a.y-3)<=4){s.gateOpen=true;s.message='冲锋壳撞开了南侧闸门。';}else{s.message='闸门太远：靠近中部再发动冲锋。';return false;}}
    if(id==='turret'){s.cameraOff=true;s.terminals.a=true;s.message='炮台壳击穿摄像头，终端 A 已接管。';}
    if(id==='scout'){s.shortcut=true;s.message='侦察壳扫描出东侧维护通道。';}
    if(id==='shield'){s.shieldTurns=5;s.message='护盾壳展开 5 回合防护，可以穿过激光区。';}
    finishTurn(s);return true;
  }
  function interact(s){if(s.phase!=='play')return false;var a=actor(s);if(a.x===2&&a.y===6){s.terminals.b=true;s.message='终端 B 已取回货物坐标。';finishTurn(s);return true;}if(a.x===10&&a.y===1&&s.terminals.a){s.message='终端 A 已在炮台壳中接管，现在可以撤离。';return false;}s.message='这里没有可接管的终端。';return false;}
  function valid(s){return s&&s.phase&&s.player&&Array.isArray(s.shells)&&s.shells.length===4&&s.turn>=0&&s.alarm>=0&&s.alarm<=3;}
  function esc(v){return String(v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
  function mount(){var host=root.document&&root.document.getElementById('shellHeistMount');if(!host)return null;var state=create(),buttons='<div class="shellHeistControls"><button aria-label="向上移动" data-shell-action="up">↑</button><button aria-label="向左移动" data-shell-action="left">←</button><button aria-label="向下移动" data-shell-action="down">↓</button><button aria-label="向右移动" data-shell-action="right">→</button><button class="primary" data-shell-action="possess">寄壳</button><button data-shell-action="leave">离壳</button><button data-shell-action="ability">能力</button><button data-shell-action="interact">交互</button></div>';
    function render(){var current=actor(state),html='<div class="shellHeistLayout"><section class="shellHeistBoard"><div class="shellHeistTop"><span>TURN '+String(state.turn).padStart(2,'0')+'</span><b>警戒 '+state.alarm+'/3</b><span>'+(state.shieldTurns?'护盾 '+state.shieldTurns:'自由行动')+'</span></div><div class="shellHeistGrid">';for(var y=0;y<H;y++)for(var x=0;x<W;x++){var wall=blocked(state,x,y),terminal=x===2&&y===6?'B':x===10&&y===1?'A':'',exit=x===state.exit.x&&y===state.exit.y?'⇧':'';var who=state.player.x===x&&state.player.y===y?'●':state.shells.find(function(e){return e.x===x&&e.y===y;});var mark=who?(who==='●'?'<b class="shellPlayer">●</b>':'<b style="color:'+TYPES[who.id].color+'">'+TYPES[who.id].mark+'</b>'):terminal||exit;html+='<button class="shellCell '+(wall?'wall ':'')+(x===8&&y>=1&&y<=6?'laser ':'')+(terminal?'terminal ':'')+'" '+(wall?'disabled ':'')+'data-shell-cell="'+x+','+y+'">'+mark+'</button>';}html+='</div>'+buttons+'<p class="shellMessage" role="status">'+esc(state.message)+'</p></section><aside class="shellHeistSide"><h2>'+esc(state.controlled==='player'?'当前：本体':TYPES[state.controlled].name)+'</h2><p>'+esc(state.controlled==='player'?'靠近敌壳后寄壳。完成 A、B 两个终端，再到 ⇧ 撤离。':TYPES[state.controlled].desc)+'</p><div class="shellObjectives"><span class="'+(state.terminals.a?'done':'')+'">A '+(state.terminals.a?'已接管':'未接管')+'</span><span class="'+(state.terminals.b?'done':'')+'">B '+(state.terminals.b?'已取回':'未取回')+'</span><span class="'+(state.phase==='won'?'done':'')+'">撤离 '+(state.phase==='won'?'完成':'未完成')+'</span></div><div class="shellLegend"><p>● 本体 · ↯ 冲锋 · ⊙ 炮台 · ⌁ 侦察 · ◇ 护盾</p><p>移动会推进回合；离开的壳会按最后方向继续走。失败后可立即重开。</p></div>'+(state.phase!=='play'?'<button class="primary" data-shell-action="restart">'+(state.phase==='won'?'再走一遍':'重新尝试')+'</button>':'')+'</aside></div>';host.innerHTML=html;}
    function action(a){if(a==='up')move(state,0,-1);else if(a==='down')move(state,0,1);else if(a==='left')move(state,-1,0);else if(a==='right')move(state,1,0);else if(a==='possess')possess(state);else if(a==='leave')leave(state);else if(a==='ability')ability(state);else if(a==='interact')interact(state);else if(a==='restart')state=create();render();}
    host.onclick=function(e){var b=e.target.closest('[data-shell-action]');if(b)action(b.dataset.shellAction);};root.addEventListener('keydown',function(e){if(!host.offsetParent)return;var m={ArrowUp:[0,-1],KeyW:[0,-1],ArrowDown:[0,1],KeyS:[0,1],ArrowLeft:[-1,0],KeyA:[-1,0],ArrowRight:[1,0],KeyD:[1,0]};if(m[e.code]){e.preventDefault();move(state,m[e.code][0],m[e.code][1]);render();}else if(e.code==='KeyE'){possess(state);render();}else if(e.code==='KeyQ'){leave(state);render();}});render();return{leave:function(){host.innerHTML='';},refresh:render};}
  root.NeonShellHeist={enter:mount,leave:function(){},debug:{create:create,move:move,possess:possess,leave:leave,ability:ability,interact:interact,valid:valid,actor:actor}};
})(window);
